using Microsoft.EntityFrameworkCore;using StayFlow.Api.Models;
namespace StayFlow.Api.Data;
public class StayFlowDbContext(DbContextOptions<StayFlowDbContext> o):DbContext(o){
 public DbSet<Hotel> Hotels=>Set<Hotel>();public DbSet<Room> Rooms=>Set<Room>();public DbSet<RoomType> RoomTypes=>Set<RoomType>();public DbSet<Guest> Guests=>Set<Guest>();
 public DbSet<Booking> Bookings=>Set<Booking>();public DbSet<Payment> Payments=>Set<Payment>();public DbSet<HousekeepingTask> HousekeepingTasks=>Set<HousekeepingTask>();
 public DbSet<MaintenanceTicket> MaintenanceTickets=>Set<MaintenanceTicket>();public DbSet<InventoryItem> Inventory=>Set<InventoryItem>();public DbSet<AppUser> Users=>Set<AppUser>();public DbSet<AuditLog> AuditLogs=>Set<AuditLog>();
 public DbSet<Notification> Notifications=>Set<Notification>(); public DbSet<Feedback> Feedbacks=>Set<Feedback>(); public DbSet<LoyaltyAccount> LoyaltyAccounts=>Set<LoyaltyAccount>(); public DbSet<LoyaltyTransaction> LoyaltyTransactions=>Set<LoyaltyTransaction>(); public DbSet<Staff> StaffMembers=>Set<Staff>(); public DbSet<Shift> Shifts=>Set<Shift>(); public DbSet<Supplier> Suppliers=>Set<Supplier>(); public DbSet<MenuItem> MenuItems=>Set<MenuItem>(); public DbSet<RestaurantOrder> RestaurantOrders=>Set<RestaurantOrder>(); public DbSet<OrderItem> OrderItems=>Set<OrderItem>(); public DbSet<Invoice> Invoices=>Set<Invoice>(); public DbSet<AutomationRule> AutomationRules=>Set<AutomationRule>();
 protected override void OnModelCreating(ModelBuilder b){
  b.Entity<Room>().HasIndex(r=>new{r.HotelId,r.Number}).IsUnique();b.Entity<Booking>().HasIndex(x=>new{x.RoomId,x.CheckIn,x.CheckOut});
  b.Entity<AppUser>().HasIndex(u=>u.Email).IsUnique();b.Entity<Payment>().Property(p=>p.Amount).HasPrecision(12,2);b.Entity<Booking>().Property(p=>p.Total).HasPrecision(12,2);b.Entity<RoomType>().Property(p=>p.BaseRate).HasPrecision(12,2);b.Entity<MaintenanceTicket>().Property(p=>p.Cost).HasPrecision(12,2);
  b.Entity<RestaurantOrder>().Property(p=>p.Total).HasPrecision(12,2);b.Entity<OrderItem>().Property(p=>p.UnitPrice).HasPrecision(12,2);b.Entity<MenuItem>().Property(p=>p.Price).HasPrecision(12,2);b.Entity<Invoice>().Property(p=>p.Total).HasPrecision(12,2);b.Entity<Invoice>().HasIndex(i=>i.Number).IsUnique();b.Entity<LoyaltyAccount>().HasIndex(a=>a.GuestId).IsUnique();b.Entity<Room>().HasOne(r=>r.RoomType).WithMany().HasForeignKey(r=>r.RoomTypeId);}}
